import{_ as e,o as i,c as l,a2 as a}from"./chunks/framework.BWuWLRhz.js";const f=JSON.parse('{"title":"Supported File Managers & Dialog Integrations","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/file-manager-support.md","filePath":"user-guide/file-manager-support.md","lastUpdated":1787586465000}'),o={name:"user-guide/file-manager-support.md"};function n(r,t,d,s,g,c){return i(),l("div",null,[...t[0]||(t[0]=[a('<h1 id="supported-file-managers-dialog-integrations" tabindex="-1">Supported File Managers &amp; Dialog Integrations <a class="header-anchor" href="#supported-file-managers-dialog-integrations" aria-label="Permalink to &quot;Supported File Managers &amp; Dialog Integrations&quot;">​</a></h1><p>Lertaro is more than a standalone search launcher — it deeply embeds into Windows File Explorer, third-party file managers, and software dialogs, dramatically streamlining file opening, saving, and folder navigation.</p><h2 id="_1-three-core-integration-capabilities" tabindex="-1">1. Three Core Integration Capabilities <a class="header-anchor" href="#_1-three-core-integration-capabilities" aria-label="Permalink to &quot;1. Three Core Integration Capabilities&quot;">​</a></h2><p>Depending on the host window&#39;s characteristics, Lertaro provides up to three distinct integration features:</p><ul><li><strong>Inline Search</strong>: Lertaro&#39;s fast search box embeds directly at the top of the host window or file dialog, enabling instant directory-scoped or global searches without context switching.</li><li><strong>Quick Navigation</strong>: Middle-click (or double-left-click) empty areas or click the embedded logo to summon a cascading menu of active folders, favorites, history, and custom categories.</li><li><strong>Active Path Detection</strong>: Senses the physical directory currently opened in the host window, scoping searches automatically and resolving relative path actions.</li></ul><h2 id="_2-native-windows-components-built-in-out-of-the-box" tabindex="-1">2. Native Windows Components (Built-in Out of the Box) <a class="header-anchor" href="#_2-native-windows-components-built-in-out-of-the-box" aria-label="Permalink to &quot;2. Native Windows Components (Built-in Out of the Box)&quot;">​</a></h2><p>These native components are supported directly by Lertaro&#39;s core engine without requiring additional plugins:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Host Window Type</th><th style="text-align:left;">Inline Search</th><th style="text-align:left;">Quick Navigation Trigger</th><th style="text-align:left;">Active Path Detection</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Windows File Explorer</strong></td><td style="text-align:left;">Supported</td><td style="text-align:left;">Double-left-click or middle-click empty areas</td><td style="text-align:left;">Supported</td></tr><tr><td style="text-align:left;"><strong>Modern Open/Save Dialogs</strong></td><td style="text-align:left;">Supported (Directly embedded)</td><td style="text-align:left;">Middle-click, or left-click the embedded logo</td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;"><strong>Legacy Open/Save Dialogs</strong></td><td style="text-align:left;">Supported</td><td style="text-align:left;">Middle-click, or left-click the embedded logo</td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;"><strong>Legacy Browse for Folder Dialogs</strong></td><td style="text-align:left;">Supported</td><td style="text-align:left;">Middle-click, or left-click the embedded logo</td><td style="text-align:left;">—</td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>In file selection dialogs, Lertaro is already directly embedded inside the window, eliminating the need for external path detection. Clicking a target in Quick Navigation jumps the dialog straight to that folder.</p></div><h2 id="_3-professional-third-party-file-managers-optional-plugins" tabindex="-1">3. Professional Third-party File Managers (Optional Plugins) <a class="header-anchor" href="#_3-professional-third-party-file-managers-optional-plugins" aria-label="Permalink to &quot;3. Professional Third-party File Managers (Optional Plugins)&quot;">​</a></h2><p>For advanced users relying on third-party file managers, Lertaro offers dedicated integration plugins. Enable them under <a href="./settings/plugins.html"><strong>Settings → Plugins</strong></a> and configure Inline Search and Quick Navigation independently:</p><table tabindex="0"><thead><tr><th style="text-align:left;">File Manager</th><th style="text-align:left;">Inline Search</th><th style="text-align:left;">Quick Navigation Trigger</th><th style="text-align:left;">Active Path Detection</th><th style="text-align:left;">Core Communication Technology</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Directory Opus</strong></td><td style="text-align:left;">Supported</td><td style="text-align:left;">Middle-click in the file list area</td><td style="text-align:left;">Supported</td><td style="text-align:left;"><code>WM_COPYDATA</code> official remote API</td></tr><tr><td style="text-align:left;"><strong>Total Commander</strong></td><td style="text-align:left;">Supported</td><td style="text-align:left;">Middle-click in the file list area</td><td style="text-align:left;">Supported</td><td style="text-align:left;"><code>WM_COPYDATA</code> message protocol</td></tr><tr><td style="text-align:left;"><strong>XYplorer</strong></td><td style="text-align:left;">Supported</td><td style="text-align:left;">Middle-click in the file list area</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Dedicated process communication</td></tr><tr><td style="text-align:left;"><strong>Files</strong></td><td style="text-align:left;">Supported</td><td style="text-align:left;">Middle-click in the file list area</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Windows UI Automation framework</td></tr><tr><td style="text-align:left;"><strong>One Commander</strong></td><td style="text-align:left;">Supported</td><td style="text-align:left;">Middle-click in the file list area</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Windows UI Automation framework</td></tr></tbody></table><h3 id="directory-opus-exclusive-deep-integration" tabindex="-1">Directory Opus Exclusive Deep Integration <a class="header-anchor" href="#directory-opus-exclusive-deep-integration" aria-label="Permalink to &quot;Directory Opus Exclusive Deep Integration&quot;">​</a></h3><ul><li><strong>Recursive Folder Size Column (Lertaro Size)</strong>: When &quot;Enable Lertaro Size Column&quot; is enabled, Lertaro installs a custom script column into Directory Opus. This column reads recursive folder sizes directly from Lertaro&#39;s in-memory index, displaying total folder sizes across entire drives in sub-seconds <strong>with zero disk I/O</strong>.</li><li><strong>Persistent Format</strong>: Add the &quot;Lertaro Size&quot; column in Directory Opus, then click <strong>Folder → Folder Formats → Save → Save Format to All Folders</strong> to make it permanent globally.</li></ul><h3 id="everything-compatibility-service-ipc" tabindex="-1">Everything Compatibility Service (IPC) <a class="header-anchor" href="#everything-compatibility-service-ipc" aria-label="Permalink to &quot;Everything Compatibility Service (IPC)&quot;">​</a></h3><p>Under <a href="./settings/general.html#system"><strong>Settings → General → System</strong></a>, enable <strong>Enable Everything Compatibility Service (IPC)</strong> to emulate the standard Everything Win32 IPC interface. Tools like Directory Opus, Total Commander, and Flow Launcher can query Lertaro&#39;s fast in-memory index directly via their existing Everything plugins.</p><h2 id="_4-custom-application-dialogs-dedicated-plugins" tabindex="-1">4. Custom Application Dialogs (Dedicated Plugins) <a class="header-anchor" href="#_4-custom-application-dialogs-dedicated-plugins" aria-label="Permalink to &quot;4. Custom Application Dialogs (Dedicated Plugins)&quot;">​</a></h2><p>Many software suites use custom-drawn windows instead of native Windows dialogs. Lertaro provides dedicated plugin integrations for these popular tools:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Application &amp; Dialog Type</th><th style="text-align:left;">Inline Search</th><th style="text-align:left;">Quick Navigation Trigger</th><th style="text-align:left;">Integration Notes</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>WPS Office</strong> Open/Save Dialogs</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Middle-click or click embedded logo</td><td style="text-align:left;">Supports WPS Writer, Spreadsheets, Presentation, and PDF</td></tr><tr><td style="text-align:left;"><strong>WinRAR</strong> Extraction Dialog</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Middle-click or click embedded logo</td><td style="text-align:left;">Quickly target destination extraction paths</td></tr><tr><td style="text-align:left;"><strong>Bandizip</strong> Extraction Dialog</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Middle-click or click embedded logo</td><td style="text-align:left;">Specify extraction output folders instantly</td></tr><tr><td style="text-align:left;"><strong>Bandizip</strong> Add Files Dialog</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Middle-click or click embedded logo</td><td style="text-align:left;">Select archive source files rapidly</td></tr><tr><td style="text-align:left;"><strong>AutoCAD</strong> Open/Save Dialogs</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Middle-click or click embedded logo</td><td style="text-align:left;">Optimized for CAD drawing retrieval and storage</td></tr></tbody></table><p>Integrations identify internal control hierarchies and handle levels, remaining fully compatible regardless of software language packs or UI skin variations.</p>',20)])])}const h=e(o,[["render",n]]);export{f as __pageData,h as default};
